import pathlib,json,html
D=pathlib.Path(__file__).resolve().parent;R=D.parents[2];O=R/'outputs'/D.name;source=R/'data/research/mobile_compact_20261026_234006/app_data.json';p=json.loads(source.read_text(encoding='utf8'));H=html.escape
notes=[]
for company in p['companies']:
 color={'黄色':'黄（最優先）','緑':'緑（次優先）','青系':'青（行けたら）'}[company['priority']]
 if company['shortName'].startswith('Wintech'):color='AI側：緑／自動化側：青（保留）'
 lines=[f"{company['company']}｜{company['booth']}｜{color}",company['hall'],'','見る展示：']
 lines += ['・'+i['name'] for i in company['items']]
 focus=[i for i in company['items'] if i['focus'].strip()]
 if focus:
  lines += ['','着眼点：']
  for i in focus:
   if len(company['items'])>1:lines.append('［'+i['name']+'］')
   lines.append(i['focus'].strip())
 lines += ['','確かめたいこと：'];questions=[i for i in company['items'] if i['questions'].strip()]
 if questions:
  for i in questions:
   if len(company['items'])>1:lines.append('［'+i['name']+'］')
   lines.append(i['questions'].strip())
 else:lines.append('未記入')
 lines += ['','――当日の音声メモ――','','']
 text='\n'.join(lines);notes.append({'id':company['id'],'company':company['company'],'shortName':company['shortName'],'booth':company['booth'],'area':company['area'],'priority':company['priority'],'text':text,'hasQuestions':bool(questions),'items':company['items']})
assert len(notes)==34 and len({n['id'] for n in notes})==34
alltext=('\n'+'━'*24+'\n\n').join(x['text'] for x in notes)
(O/'JIMTOF2026_訪問予定34社_メモ貼付用.txt').write_text(alltext,encoding='utf-8-sig')
(D/'notes.json').write_text(json.dumps({'source':str(source.relative_to(R)),'scope':'現在の訪問予定34社。追加候補ページの端末内判断は未取込み。','notes':notes},ensure_ascii=False,indent=2),encoding='utf8')
cards=[]
for n in notes:
 css={'黄色':'y','緑':'g','青系':'b'}[n['priority']];cards.append(f'''<article class="{css}" id="note-{n['id']}"><div class="row"><details><summary><span>{H(n['shortName'])}</span><small>{H(n['booth'])}</small></summary><pre>{H(n['text'])}</pre></details><button type="button" data-copy="{n['id']}" aria-label="{H(n['company'])}をコピー">コピー</button></div></article>''')
page=r'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>訪問予定34社｜メモへコピー</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6f7;color:#233c49;font:16px/1.6 -apple-system,BlinkMacSystemFont,"Yu Gothic UI",Meiryo,sans-serif;overflow-wrap:anywhere}header{position:sticky;top:0;background:white;z-index:5;border-bottom:1px solid #bfced6;padding:9px 10px}.heading{display:flex;justify-content:space-between;align-items:center;gap:8px}h1{font-size:17px;margin:0}a{color:#075e8e}header a{font-size:14px}header p{font-size:13px;margin:4px 0;color:#55717e}.tools{display:flex;gap:6px;margin-top:6px}.tools input{flex:1;min-width:0;border:1px solid #b7cbd5;padding:7px;font:inherit;border-radius:4px}.tools button{white-space:nowrap}button{border:1px solid #aac3d1;background:#edf5f8;color:#145270;border-radius:4px;padding:8px 10px;min-height:42px;font:inherit;font-size:14px;cursor:pointer}main{max-width:850px;margin:auto;padding:5px 8px 25px}article{background:white;border:1px solid #d2dfe6;border-top:0;border-left:5px solid #d2dfe6}article.y{border-left-color:#dfc500}article.g{border-left-color:#78a75b}article.b{border-left-color:#6aa4cf}.row{display:grid;grid-template-columns:minmax(0,1fr) 65px;align-items:start}.row>button{margin:5px 4px 5px 0;padding:7px 4px}details{min-width:0}summary{display:flex;justify-content:space-between;gap:8px;align-items:center;list-style:none;min-height:52px;padding:10px 8px;cursor:pointer}summary::-webkit-details-marker{display:none}summary span{font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}summary small{font-size:13px;white-space:nowrap}pre{font-family:inherit;font-size:15px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere;margin:0;padding:6px 10px 12px;border-top:1px solid #dce5e9}#status{min-height:21px;font-size:13px;color:#256a51}.info{font-size:14px;padding:8px 2px;color:#4c6b7c}.info details{padding:5px 0}.info summary{padding:0;min-height:34px;justify-content:flex-start}dialog{max-width:94vw;width:600px;border:1px solid #b6cbd6;border-radius:8px;padding:15px}dialog::backdrop{background:#0005}dialog h2{font-size:18px;margin:0 0 8px}dialog textarea{width:100%;min-height:250px;font:16px/1.6 sans-serif;padding:8px}dialog button{margin-top:8px}.fallback p{font-size:14px}@media(min-width:850px){header{padding-left:max(10px,calc((100% - 830px)/2));padding-right:max(10px,calc((100% - 830px)/2))}}</style></head><body><header><div class="heading"><h1>訪問予定34社・メモ貼付用</h1><a href="https://jio-n.github.io/J_research/">訪問一覧</a></div><p>企業ごとにコピー → iPhoneのメモへ貼付</p><div class="tools"><input id="search" type="search" aria-label="企業・ブースを検索" placeholder="企業・ブース"><button id="copyAll" type="button">全34社コピー</button></div><div id="status" role="status" aria-live="polite">企業名をタップすると貼付内容を確認できます</div></header><main><div class="info">現在の訪問予定34社分です。候補抽出ページで端末内に付けた判断は、まだ含まれていません。<details><summary>録音と未記入欄について</summary><p>当日は項目を振り分けず、「当日の音声メモ」以下へ一続きで入力。最初に企業名・アイテム名を話せば後で整理できます。事前の着眼点・質問は既存資料の文言を保持し、未記入の企業には質問を新しく作っていません。</p></details></div><div id="list">__CARDS__</div></main><dialog id="fallback" class="fallback"><h2>コピーする内容</h2><p>自動コピーできない場合は、下の文章を長押しして「すべて選択」→「コピー」を選んでください。</p><textarea id="fallbackText" readonly aria-label="コピー用テキスト"></textarea><button id="close" type="button">閉じる</button></dialog><script type="application/json" id="noteData">__DATA__</script><script>
'use strict';const notes=JSON.parse(document.getElementById('noteData').textContent),map=new Map(notes.map(x=>[x.id,x])),status=document.getElementById('status');async function copy(text,label){try{if(!navigator.clipboard?.writeText)throw Error('clipboard unavailable');await navigator.clipboard.writeText(text);status.textContent=label+'をコピーしました。メモに貼り付けてください。';}catch{const d=document.getElementById('fallback'),t=document.getElementById('fallbackText');t.value=text;d.showModal();t.focus();t.select();status.textContent='コピー用の文章を開きました。';}}for(const b of document.querySelectorAll('[data-copy]'))b.onclick=()=>{const n=map.get(b.dataset.copy);copy(n.text,n.shortName)};document.getElementById('copyAll').onclick=()=>copy(notes.map(x=>x.text).join('\n'+'━'.repeat(24)+'\n\n'),'全34社');document.getElementById('close').onclick=()=>document.getElementById('fallback').close();document.getElementById('search').oninput=e=>{const q=e.target.value.trim().toLocaleLowerCase();for(const n of notes)document.getElementById('note-'+n.id).hidden=Boolean(q&&!JSON.stringify([n.company,n.booth]).toLocaleLowerCase().includes(q));};
</script></body></html>'''
page=page.replace('__CARDS__',''.join(cards)).replace('__DATA__',json.dumps(notes,ensure_ascii=False).replace('<','\\u003c'));(O/'notes.html').write_text(page,encoding='utf8')
print(json.dumps({'companies':34,'items':sum(len(n['items']) for n in notes),'text_characters':len(alltext),'without_questions':sum(not n['hasQuestions'] for n in notes)},ensure_ascii=False))
